4	export const productService = {
5	  // Get all products with categories (Public access)
6	  async getProducts(filters = {}) {
7	    try {
8	      let query = supabase?.from('products')?.select(`
9	          id,
10	          name,
11	          description,
12	          price,
13	          image_url,
14	          is_active,
15	          category_id,
16	          created_at,
17	          updated_at,
18	          categories (
19	            id,
20	            name,
21	            restaurant_id
22	          )
23	        `)?.eq('is_active', true)
24	      
25	      // Apply filters
26	      if (filters?.categoryId) {
27	        query = query?.eq('category_id', filters?.categoryId)
28	      }
29	      
30	      if (filters?.searchTerm) {
31	        query = query?.ilike('name', `%${filters?.searchTerm}%`)
32	      }
33	      
34	      if (filters?.maxPrice) {
35	        query = query?.lte('price', filters?.maxPrice)
36	      }
37	      
38	      if (filters?.minPrice) {
39	        query = query?.gte('price', filters?.minPrice)
40	      }
41	      
42	      const { data, error } = await query?.order('name', { ascending: true })
43	      
44	      if (error) return { success: false, error: error?.message };
45	      return { success: true, products: data || [] }
46	    } catch (error) {
47	      return { success: false, error: 'Failed to fetch products' }
48	    }
49	  },
50	
51	  // Get products by restaurant
52	  async getProductsByRestaurant(restaurantId) {
53	    try {
54	      const { data, error } = await supabase?.from('products')?.select(`
55	          id,
56	          name,
57	          description,
58	          price,
59	          image_url,
60	          is_active,
61	          category_id,
62	          categories (
63	            id,
64	            name,
65	            restaurant_id
66	          )
67	        `)?.eq('categories.restaurant_id', restaurantId)?.eq('is_active', true)?.order('category_id')?.order('name')
68	      
69	      if (error) return { success: false, error: error?.message };
70	      return { success: true, products: data || [] }
71	    } catch (error) {
72	      return { success: false, error: 'Failed to fetch restaurant products' }
73	    }
74	  },
75	
76	  // Get single product by ID
77	  async getProduct(productId) {
78	    try {
79	      const { data, error } = await supabase?.from('products')?.select(`
80	          id,
81	          name,
82	          description,
83	          price,
84	          image_url,
85	          is_active,
86	          category_id,
87	          created_at,
88	          updated_at,
89	          categories (
90	            id,
91	            name,
92	            restaurant_id
93	          )
94	        `)?.eq('id', productId)?.single()
95	      
96	      if (error) return { success: false, error: error?.message };
97	      return { success: true, product: data }
98	    } catch (error) {
99	      return { success: false, error: 'Failed to fetch product' }
100	    }
101	  },
102	
103	  // Create new product (Admin only)
104	  async createProduct(productData) {
105	    try {
106	      const { data, error } = await supabase?.from('products')?.insert([{
107	          name: productData?.name,
108	          description: productData?.description,
109	          price: productData?.price,
110	          image_url: productData?.image_url,
111	          category_id: productData?.category_id,
112	          is_active: productData?.is_active !== undefined ? productData?.is_active : true
113	        }])?.select(`
114	          id,
115	          name,
116	          description,
117	          price,
118	          image_url,
119	          is_active,
120	          category_id,
121	          categories (
122	            id,
123	            name,
124	            restaurant_id
125	          )
126	        `)?.single()
127	      
128	      if (error) return { success: false, error: error?.message };
129	      return { success: true, product: data }
130	    } catch (error) {
131	      return { success: false, error: 'Failed to create product' }
132	    }
