156	  private async verificarProdutoDoRestaurante(produtoId: number, restaurantId: number) {
157	    const { data: prod } = await this.supabase.client
158	      .from('products').select('id, category_id, restaurant_id').eq('id', produtoId).maybeSingle();
159	    if (!prod) throw new NotFoundException('Produto não encontrado');
160	    if (prod.restaurant_id !== restaurantId) throw new NotFoundException('Produto não pertence a este restaurante');
161	    return prod;
162	  }
163	
164	  async meusProdutos(restaurantId: number) {
165	    const { data, error } = await this.supabase.client
166	      .from('products')
167	      .select('id, name, description, price, preco_promo, image_url, is_active, category_id, restaurant_id, tags, destaque, impressora_id, quantidade_estoque, created_at, categories(name)')
168	      .eq('restaurant_id', restaurantId)
169	      .order('destaque', { ascending: false })
170	      .order('name');
171	
172	    if (error) throw error;
173	    // category_name direto no produto (igual ao endpoint do garçom) pra telas com
174	    // filtro por categoria não precisarem buscar/montar o map à parte.
175	    const produtos = (data ?? []).map((p: any) => ({ ...p, category_name: p.categories?.name ?? 'Outros' }));
176	    return { produtos };
177	  }
178	
179	  async criarProduto(
180	    restaurantId: number,
181	    body: {
182	      name: string; description?: string; price: number; image_url?: string;
183	      category_id: number; tags?: string[]; preco_promo?: number; destaque?: boolean;
184	      impressora_id?: number; quantidade_estoque?: number;
185	    },
186	  ) {
187	    // Valida se a categoria é do restaurante ou global (restaurant_id IS NULL)
188	    const { data: cat } = await this.supabase.client
189	      .from('categories').select('id, restaurant_id').eq('id', body.category_id).maybeSingle();
190	    if (!cat) throw new NotFoundException('Categoria não encontrada');
191	    if (cat.restaurant_id !== null && cat.restaurant_id !== restaurantId)
192	      throw new NotFoundException('Categoria não pertence a este restaurante');
193	
194	    const { data, error } = await this.supabase.client
195	      .from('products')
196	      .insert({
